#pragma once#include <rsuErr.h>#include <HcdMemoryService.h>class KDynString{  LPSTR m_pString;private:  void AssignString( LPCSTR pszSrc )  {    size_t len = strlen( pszSrc );    if( !len )    {      Test4Null();      return;    }    m_pString = (LPSTR)KMemoryServiceHCD::Instance().NewMem( len+1 );    strcpy_s( m_pString, len+1, pszSrc );  }  void Test4Null()  {    if( m_pString )      return;    m_pString = (LPSTR)KMemoryServiceHCD::Instance().NewMem( 1 );    *m_pString= 0;  }public:  KDynString() : m_pString( NULL )  {  }  KDynString( LPCSTR pszThr )  {    AssignString( pszThr );  }  void operator = ( LPCSTR pszThr )  {    AssignString( pszThr );  }  operator LPCSTR()  {    Test4Null();    return m_pString;  }  bool empty()  {    return !m_pString;  }  size_t length() const  {    if( !m_pString )      return 0;    return strlen(m_pString);  }};